import sys

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    n = data[0]
    nums = data[1:1+n] if n > 0 else []
    total = 0
    for i in range(n):
        xi = nums[i]
        for j in range(i):
            if nums[j] < xi:
                total += nums[j]
    print(total)

if __name__ == "__main__":
    main()
